/**
 * Mystery Jungle — pure generation / solving / validation logic (no React).
 * Every puzzle is deterministic: same seed + params => same puzzle.
 *
 *  - Maze:        seeded recursive-backtracker perfect maze, BFS path, corridor runs, keys (gems)
 *  - Path finder: grid with obstacles, fewest-turn shortest path, arrow-list distractors, program simulation
 *  - Push puzzle: sokoban room generated by reverse play (pulls) + push-level BFS solver
 *  - Hidden:      jungle scene layout with non-overlapping targets/distractors and covering leaves
 */
import { createRng, type Rng } from '@/engine/rng';
import type { ItemName } from '@/art/items';

/* ------------------------------------------------------------------ grid */

export type Dir = 'U' | 'R' | 'D' | 'L';
export const DIRS: readonly Dir[] = ['U', 'R', 'D', 'L'];
export const DR: Record<Dir, number> = { U: -1, R: 0, D: 1, L: 0 };
export const DC: Record<Dir, number> = { U: 0, R: 1, D: 0, L: -1 };
export const OPPOSITE: Record<Dir, Dir> = { U: 'D', D: 'U', L: 'R', R: 'L' };

/** Neighbour index of cell i in direction d on a cols x rows grid, or -1 when off the grid. */
export function stepCell(i: number, d: Dir, cols: number, rows: number): number {
  const r = Math.floor(i / cols) + DR[d];
  const c = (i % cols) + DC[d];
  if (r < 0 || c < 0 || r >= rows || c >= cols) return -1;
  return r * cols + c;
}

/** Direction from cell a to adjacent cell b. */
export function dirBetween(a: number, b: number, cols: number): Dir {
  if (b === a - cols) return 'U';
  if (b === a + cols) return 'D';
  if (b === a + 1) return 'R';
  return 'L';
}

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));

/** Generic BFS over a grid. `passable(from, to, dir)` decides edges. Returns distances (-1 = unreachable). */
export function bfsDistances(
  cols: number,
  rows: number,
  from: number,
  passable: (from: number, to: number, d: Dir) => boolean,
): number[] {
  const dist = new Array<number>(cols * rows).fill(-1);
  dist[from] = 0;
  const q = [from];
  for (let h = 0; h < q.length; h++) {
    const cur = q[h];
    for (const d of DIRS) {
      const nx = stepCell(cur, d, cols, rows);
      if (nx < 0 || dist[nx] >= 0 || !passable(cur, nx, d)) continue;
      dist[nx] = dist[cur] + 1;
      q.push(nx);
    }
  }
  return dist;
}

/** BFS shortest path (cells from `from` to `to`, inclusive) or null. */
export function bfsPath(
  cols: number,
  rows: number,
  from: number,
  to: number,
  passable: (from: number, to: number, d: Dir) => boolean,
): number[] | null {
  const prev = new Array<number>(cols * rows).fill(-2);
  prev[from] = -1;
  const q = [from];
  for (let h = 0; h < q.length; h++) {
    const cur = q[h];
    if (cur === to) break;
    for (const d of DIRS) {
      const nx = stepCell(cur, d, cols, rows);
      if (nx < 0 || prev[nx] !== -2 || !passable(cur, nx, d)) continue;
      prev[nx] = cur;
      q.push(nx);
    }
  }
  if (prev[to] === -2) return null;
  const path: number[] = [];
  for (let c = to; c !== -1; c = prev[c]) path.push(c);
  return path.reverse();
}

export function pathToDirs(path: number[], cols: number): Dir[] {
  const out: Dir[] = [];
  for (let i = 1; i < path.length; i++) out.push(dirBetween(path[i - 1], path[i], cols));
  return out;
}

/* ------------------------------------------------------------------ maze */

export interface MazeParams {
  /** cells per side (5..15) */
  size: number;
  /** gems to collect before the temple gate opens */
  keys?: number;
  /** count wall bumps as mistakes (gently, rate limited in the UI) */
  bumpPenalty?: boolean;
}

export interface Maze {
  size: number;
  /** wall bitmask per cell (WALL_BIT); a set bit = wall present */
  walls: number[];
  start: number;
  goal: number;
  keys: number[];
}

export const WALL_BIT: Record<Dir, number> = { U: 1, R: 2, D: 4, L: 8 };

export function generateMaze(seed: number, p: MazeParams): Maze {
  const rng = createRng(seed);
  const n = clamp(Math.round(p.size || 5), 3, 15);
  const walls = new Array<number>(n * n).fill(15);
  const seen = new Array<boolean>(n * n).fill(false);
  // recursive backtracker (iterative)
  const first = rng.int(0, n * n - 1);
  const stack = [first];
  seen[first] = true;
  while (stack.length) {
    const cur = stack[stack.length - 1];
    const opts = rng.shuffle(DIRS).filter((d) => {
      const nx = stepCell(cur, d, n, n);
      return nx >= 0 && !seen[nx];
    });
    if (!opts.length) {
      stack.pop();
      continue;
    }
    const d = opts[0];
    const nx = stepCell(cur, d, n, n);
    walls[cur] &= ~WALL_BIT[d];
    walls[nx] &= ~WALL_BIT[OPPOSITE[d]];
    seen[nx] = true;
    stack.push(nx);
  }
  const corners = [(n - 1) * n, n * n - 1, 0, n - 1];
  const start = rng.pick(corners);
  const maze: Maze = { size: n, walls, start, goal: start, keys: [] };
  const dist = mazeDistances(maze, start);
  let goal = start;
  dist.forEach((d, i) => {
    if (d > dist[goal]) goal = i;
  });
  maze.goal = goal;
  const k = clamp(Math.round(p.keys ?? 0), 0, 6);
  if (k > 0) {
    const deadEnds = rng.shuffle(
      walls.map((_, i) => i).filter((i) => i !== start && i !== goal && openDirs(maze, i).length === 1 && dist[i] >= 3),
    );
    const others = rng.shuffle(walls.map((_, i) => i).filter((i) => i !== start && i !== goal && !deadEnds.includes(i) && dist[i] >= 2));
    const pool = [...deadEnds, ...others];
    const keys: number[] = [];
    for (const c of pool) {
      if (keys.length >= k) break;
      // keep gems apart so the player explores
      if (keys.every((o) => Math.abs((o % n) - (c % n)) + Math.abs(Math.floor(o / n) - Math.floor(c / n)) >= 2)) keys.push(c);
    }
    maze.keys = keys;
  }
  return maze;
}

export function mazeOpen(m: Maze, i: number, d: Dir): boolean {
  return (m.walls[i] & WALL_BIT[d]) === 0 && stepCell(i, d, m.size, m.size) >= 0;
}

export function openDirs(m: Maze, i: number): Dir[] {
  return DIRS.filter((d) => mazeOpen(m, i, d));
}

export function mazeDistances(m: Maze, from: number): number[] {
  return bfsDistances(m.size, m.size, from, (a, _b, d) => mazeOpen(m, a, d));
}

export function mazePath(m: Maze, from: number, to: number): number[] | null {
  return bfsPath(m.size, m.size, from, to, (a, _b, d) => mazeOpen(m, a, d));
}

/**
 * Walks from `from` in direction `dir` and keeps following the corridor (round corners)
 * until a junction, a dead end, or a cell in `stopAt`. Returns visited cells (excluding `from`).
 * Empty array = the first step hits a wall.
 */
export function mazeRun(m: Maze, from: number, dir: Dir, stopAt: Set<number>): number[] {
  const out: number[] = [];
  let cur = from;
  let d = dir;
  while (out.length < m.size * m.size) {
    if (!mazeOpen(m, cur, d)) break;
    cur = stepCell(cur, d, m.size, m.size);
    out.push(cur);
    if (stopAt.has(cur)) break;
    const exits = DIRS.filter((x) => x !== OPPOSITE[d] && mazeOpen(m, cur, x));
    if (exits.length !== 1) break;
    d = exits[0];
  }
  return out;
}

/** Validation helper: connected, perfect (tree => n*n-1 passages), symmetric walls, borders closed. */
export function validateMaze(m: Maze): string | null {
  const n = m.size;
  let passages = 0;
  for (let i = 0; i < n * n; i++) {
    for (const d of DIRS) {
      const nx = stepCell(i, d, n, n);
      const open = (m.walls[i] & WALL_BIT[d]) === 0;
      if (nx < 0) {
        if (open) return `border open at ${i}`;
        continue;
      }
      const back = (m.walls[nx] & WALL_BIT[OPPOSITE[d]]) === 0;
      if (open !== back) return `asymmetric wall at ${i}`;
      if (open && (d === 'R' || d === 'D')) passages++;
    }
  }
  if (passages !== n * n - 1) return `not perfect: ${passages} passages`;
  const dist = mazeDistances(m, m.start);
  if (dist.some((d) => d < 0)) return 'not connected';
  if (m.start === m.goal) return 'start == goal';
  if (m.keys.some((k) => k === m.start || k === m.goal)) return 'key on start/goal';
  return null;
}

/* ----------------------------------------------------------- path finder */

export type ObstacleKind = 'rock' | 'water' | 'bush';

export interface PathParams {
  size: number;
  mode?: 'choose' | 'program';
  obstacles?: number;
  /** length of the shortest route (moves) */
  steps?: number;
  /** puzzles to solve in this stage */
  rounds?: number;
}

export interface PathChoice {
  key: string;
  dirs: Dir[];
}

export interface PathPuzzle {
  size: number;
  start: number;
  treasure: number;
  obstacles: (ObstacleKind | null)[];
  /** fewest-turn shortest route */
  solution: Dir[];
  choices: PathChoice[];
  correctKey: string;
}

export interface Run {
  dir: Dir;
  count: number;
}

export function toRuns(dirs: Dir[]): Run[] {
  const out: Run[] = [];
  for (const d of dirs) {
    const last = out[out.length - 1];
    if (last && last.dir === d) last.count++;
    else out.push({ dir: d, count: 1 });
  }
  return out;
}

export function fromRuns(runs: Run[]): Dir[] {
  const out: Dir[] = [];
  for (const r of runs) for (let i = 0; i < r.count; i++) out.push(r.dir);
  return out;
}

export const runsKey = (dirs: Dir[]) =>
  toRuns(dirs)
    .map((r) => `${r.dir}${r.count}`)
    .join('');

export interface ProgramResult {
  /** cells walked through, starting with the start cell */
  cells: number[];
  /** move index that bumped into an obstacle/edge, or -1 */
  crashAt: number;
  /** move index after which the treasure was reached, or -1 */
  reachedAt: number;
}

/** Walks the program; stops at a crash or as soon as the treasure is reached. */
export function runProgram(p: Pick<PathPuzzle, 'size' | 'start' | 'treasure' | 'obstacles'>, dirs: Dir[]): ProgramResult {
  const cells = [p.start];
  let cur = p.start;
  for (let i = 0; i < dirs.length; i++) {
    const nx = stepCell(cur, dirs[i], p.size, p.size);
    if (nx < 0 || p.obstacles[nx]) return { cells, crashAt: i, reachedAt: -1 };
    cur = nx;
    cells.push(cur);
    if (cur === p.treasure) return { cells, crashAt: -1, reachedAt: i };
  }
  return { cells, crashAt: -1, reachedAt: -1 };
}

/** Shortest path with the fewest turns (nicer arrow lists). */
function fewestTurnPath(size: number, obstacles: (ObstacleKind | null)[], start: number, goal: number): Dir[] | null {
  const pass = (_a: number, b: number) => !obstacles[b];
  const d0 = bfsDistances(size, size, start, pass);
  const dT = bfsDistances(size, size, goal, pass);
  const L = d0[goal];
  if (L < 0) return null;
  // DP over shortest-path DAG, state = cell*4 + incoming dir
  const INF = 1e9;
  const cost = new Array<number>(size * size * 4).fill(INF);
  const prev = new Array<number>(size * size * 4).fill(-1);
  const layers: number[][] = Array.from({ length: L + 1 }, () => []);
  for (let i = 0; i < size * size; i++) if (d0[i] >= 0 && dT[i] >= 0 && d0[i] + dT[i] === L) layers[d0[i]].push(i);
  for (let di = 0; di < 4; di++) cost[start * 4 + di] = 0;
  for (let l = 0; l < L; l++) {
    for (const cell of layers[l]) {
      for (let pd = 0; pd < 4; pd++) {
        const c0 = cost[cell * 4 + pd];
        if (c0 >= INF) continue;
        DIRS.forEach((d, di) => {
          const nx = stepCell(cell, d, size, size);
          if (nx < 0 || obstacles[nx] || d0[nx] !== l + 1 || d0[nx] + dT[nx] !== L) return;
          const c = c0 + (l > 0 && di !== pd ? 1 : 0);
          if (c < cost[nx * 4 + di]) {
            cost[nx * 4 + di] = c;
            prev[nx * 4 + di] = cell * 4 + pd;
          }
        });
      }
    }
  }
  let best = -1;
  for (let di = 0; di < 4; di++) if (best < 0 || cost[goal * 4 + di] < cost[best]) best = goal * 4 + di;
  if (best < 0 || cost[best] >= INF) return null;
  const dirs: Dir[] = [];
  let s = best;
  for (let k = 0; k < L; k++) {
    if (s < 0) return null;
    dirs.push(DIRS[s % 4]);
    s = prev[s];
  }
  return dirs.reverse();
}

function mutateRuns(rng: Rng, runs: Run[]): Run[] {
  const out = runs.map((r) => ({ ...r }));
  const i = rng.int(0, out.length - 1);
  const kind = rng.int(0, 5);
  const perp = (d: Dir): Dir[] => (d === 'U' || d === 'D' ? ['L', 'R'] : ['U', 'D']);
  if (kind === 0) out[i].dir = rng.pick(perp(out[i].dir));
  else if (kind === 1) out[i].dir = OPPOSITE[out[i].dir];
  else if (kind === 2) out[i].count += rng.chance(0.5) ? 1 : -1;
  else if (kind === 3 && out.length > 1) {
    const j = i === out.length - 1 ? i - 1 : i + 1;
    [out[i], out[j]] = [out[j], out[i]];
  } else if (kind === 4) out[i].count += rng.chance(0.5) ? 2 : -1;
  else out.splice(rng.int(0, out.length), 0, { dir: rng.pick(DIRS), count: rng.int(1, 2) });
  return toRuns(fromRuns(out.filter((r) => r.count > 0)));
}

export function generatePathPuzzle(seed: number, p: PathParams, round = 0): PathPuzzle {
  const rng = createRng(seed + round * 7717);
  const size = clamp(Math.round(p.size || 4), 3, 7);
  const want = clamp(Math.round(p.steps ?? size), 2, size * size - 2);
  const nObs = clamp(Math.round(p.obstacles ?? 0), 0, Math.floor(size * size * 0.35));
  let fallback: PathPuzzle | null = null;
  for (let attempt = 0; attempt < 400; attempt++) {
    const obstacles: (ObstacleKind | null)[] = new Array(size * size).fill(null);
    const cells = rng.shuffle(Array.from({ length: size * size }, (_, i) => i));
    for (let k = 0; k < nObs; k++) obstacles[cells[k]] = rng.pick<ObstacleKind>(['rock', 'rock', 'bush', 'water']);
    const free = cells.slice(nObs);
    const start = rng.pick(free);
    const dist = bfsDistances(size, size, start, (_a, b) => !obstacles[b]);
    let cands = free.filter((c) => dist[c] === want);
    if (!cands.length && attempt > 300) cands = free.filter((c) => dist[c] >= Math.max(2, want - 2) && dist[c] <= want + 1);
    if (!cands.length) continue;
    const treasure = rng.pick(cands);
    const solution = fewestTurnPath(size, obstacles, start, treasure);
    if (!solution) continue;
    const correctKey = runsKey(solution);
    const base = { size, start, treasure, obstacles };
    const distractors: PathChoice[] = [];
    const used = new Set([correctKey]);
    const runs = toRuns(solution);
    for (let t = 0; t < 400 && distractors.length < 3; t++) {
      let m = mutateRuns(rng, runs);
      if (rng.chance(0.3)) m = mutateRuns(rng, m);
      const dirs = fromRuns(m);
      if (!dirs.length || dirs.length > solution.length + 3) continue;
      const key = runsKey(dirs);
      if (used.has(key)) continue;
      const res = runProgram(base, dirs);
      if (res.reachedAt >= 0) continue; // must not reach the treasure at all
      used.add(key);
      distractors.push({ key, dirs });
    }
    if (distractors.length < 3) continue;
    const choices = rng.shuffle([{ key: correctKey, dirs: solution }, ...distractors]);
    const puz: PathPuzzle = { ...base, solution, choices, correctKey };
    // prefer puzzles where obstacles actually matter (no straight Manhattan sprint with zero turns)
    const turns = toRuns(solution).length;
    if (turns >= Math.min(3, Math.ceil(want / 2)) || attempt > 250) return puz;
    fallback = fallback ?? puz;
  }
  if (fallback) return fallback;
  // ultra-safe fallback: obstacle-free straight puzzle
  const obstacles = new Array(size * size).fill(null);
  const solution: Dir[] = [...Array(size - 1).fill('R'), 'U'];
  const start = (size - 1) * size;
  const treasure = (size - 2) * size + size - 1;
  return {
    size,
    start,
    treasure,
    obstacles,
    solution,
    choices: [
      { key: runsKey(solution), dirs: solution },
      { key: 'U1', dirs: ['U'] },
      { key: 'R1', dirs: ['R'] },
      { key: 'L1', dirs: ['L'] },
    ],
    correctKey: runsKey(solution),
  };
}

/* ------------------------------------------------------------ push puzzle */

export interface PushParams {
  /** playable room width/height (4..8); a wall border is added around it */
  size: number;
  crates: number;
  /** number of reverse pulls used to scramble the solved state */
  scramble?: number;
  /** inner rock blocks */
  rocks?: number;
}

export interface PushGrid {
  cols: number;
  rows: number;
  wall: boolean[];
  pads: number[];
}

export interface PushState {
  player: number;
  crates: number[];
}

export interface PushPuzzle extends PushGrid {
  start: PushState;
  /** optimal number of pushes */
  minPushes: number;
}

export interface Push {
  /** crate cell before the push */
  crate: number;
  dir: Dir;
}

export type MoveKind = 'walk' | 'push' | 'blocked';

export function applyMove(g: PushGrid, s: PushState, d: Dir): { state: PushState; kind: MoveKind } {
  const nx = stepCell(s.player, d, g.cols, g.rows);
  if (nx < 0 || g.wall[nx]) return { state: s, kind: 'blocked' };
  const ci = s.crates.indexOf(nx);
  if (ci < 0) return { state: { player: nx, crates: s.crates }, kind: 'walk' };
  const beyond = stepCell(nx, d, g.cols, g.rows);
  if (beyond < 0 || g.wall[beyond] || s.crates.includes(beyond)) return { state: s, kind: 'blocked' };
  const crates = s.crates.slice();
  crates[ci] = beyond;
  return { state: { player: nx, crates }, kind: 'push' };
}

export function isPushSolved(g: PushGrid, s: PushState): boolean {
  return s.crates.every((c) => g.pads.includes(c));
}

function isCornerDead(g: PushGrid, cell: number): boolean {
  if (g.pads.includes(cell)) return false;
  const w = (d: Dir) => {
    const n = stepCell(cell, d, g.cols, g.rows);
    return n < 0 || g.wall[n];
  };
  return (w('U') || w('D')) && (w('L') || w('R'));
}

/** Push-level BFS (optimal in pushes). Returns the pushes, [] if already solved, null if unsolvable/too big. */
export function solvePush(g: PushGrid, s: PushState, maxNodes = 200000): Push[] | null {
  if (isPushSolved(g, s)) return [];
  const N = g.cols * g.rows;
  const padSet = new Set(g.pads);
  const dead = new Uint8Array(N);
  for (let i = 0; i < N; i++) if (!g.wall[i] && isCornerDead(g, i)) dead[i] = 1;
  // numeric state key: sorted crate cells + normalized player cell, base N
  const keyOf = (crates: number[], norm: number) => {
    const sorted = crates.slice().sort((a, b) => a - b);
    let k = norm;
    for (const c of sorted) k = k * N + c;
    return k;
  };
  const occ = new Uint8Array(N);
  const seen = new Uint8Array(N);
  const q2 = new Int32Array(N);
  // flood fill from player with crates in occ; returns min reachable cell (seen[] filled)
  const flood = (player: number) => {
    seen.fill(0);
    seen[player] = 1;
    let min = player;
    let head = 0;
    let tail = 0;
    q2[tail++] = player;
    while (head < tail) {
      const cur = q2[head++];
      const nb = [cur - g.cols, cur + 1, cur + g.cols, cur - 1];
      for (const nx of nb) {
        if (nx < 0 || nx >= N || seen[nx] || g.wall[nx] || occ[nx]) continue;
        seen[nx] = 1;
        if (nx < min) min = nx;
        q2[tail++] = nx;
      }
    }
    return min;
  };
  const setOcc = (crates: number[], v: number) => {
    for (const c of crates) occ[c] = v;
  };
  setOcc(s.crates, 1);
  const startKey = keyOf(s.crates, flood(s.player));
  setOcc(s.crates, 0);
  const parent = new Map<number, { prev: number; push: Push | null }>();
  parent.set(startKey, { prev: -1, push: null });
  const q: { crates: number[]; player: number; key: number }[] = [{ crates: s.crates.slice(), player: s.player, key: startKey }];
  for (let h = 0; h < q.length; h++) {
    if (parent.size > maxNodes) return null;
    const cur = q[h];
    setOcc(cur.crates, 1);
    flood(cur.player);
    const standable = seen.slice();
    for (let ci = 0; ci < cur.crates.length; ci++) {
      const c = cur.crates[ci];
      for (const d of DIRS) {
        const stand = stepCell(c, OPPOSITE[d], g.cols, g.rows);
        const to = stepCell(c, d, g.cols, g.rows);
        if (stand < 0 || to < 0 || !standable[stand] || g.wall[to] || occ[to] || dead[to]) continue;
        const crates = cur.crates.slice();
        crates[ci] = to;
        occ[c] = 0;
        occ[to] = 1;
        const norm = flood(c);
        occ[to] = 0;
        occ[c] = 1;
        const key = keyOf(crates, norm);
        if (parent.has(key)) continue;
        parent.set(key, { prev: cur.key, push: { crate: c, dir: d } });
        if (crates.every((x) => padSet.has(x))) {
          setOcc(cur.crates, 0);
          const out: Push[] = [];
          for (let k = key; k !== -1; k = parent.get(k)!.prev) {
            const e = parent.get(k)!;
            if (e.push) out.push(e.push);
          }
          return out.reverse();
        }
        q.push({ crates, player: c, key });
      }
    }
    setOcc(cur.crates, 0);
  }
  return null;
}

/** Walk path (as moves) for the player to `to` avoiding walls and crates, or null. */
export function walkTo(g: PushGrid, s: PushState, to: number): Dir[] | null {
  const crates = new Set(s.crates);
  const path = bfsPath(g.cols, g.rows, s.player, to, (_a, b) => !g.wall[b] && !crates.has(b));
  return path ? pathToDirs(path, g.cols) : null;
}

/** Turns a push solution into individual moves (walks + pushes). */
export function expandPushSolution(g: PushGrid, s: PushState, pushes: Push[]): Dir[] | null {
  const moves: Dir[] = [];
  let st = s;
  for (const p of pushes) {
    const stand = stepCell(p.crate, OPPOSITE[p.dir], g.cols, g.rows);
    const walk = walkTo(g, st, stand);
    if (!walk) return null;
    for (const d of [...walk, p.dir]) {
      st = applyMove(g, st, d).state;
      moves.push(d);
    }
  }
  return moves;
}

export function generatePushPuzzle(seed: number, p: PushParams): PushPuzzle {
  const rng = createRng(seed);
  const inner = clamp(Math.round(p.size || 5), 3, 8);
  const cols = inner + 2;
  const rows = inner + 2;
  const nCrates = clamp(Math.round(p.crates || 1), 1, 4);
  const scramble = clamp(Math.round(p.scramble ?? 6 + nCrates * 4), 2, 60);
  const nRocks = clamp(Math.round(p.rocks ?? Math.max(0, inner - 4) * 2), 0, Math.floor(inner * inner * 0.25));
  const minPushes = Math.min(scramble, nCrates * 2 + (inner >= 6 ? 1 : 0));
  let best: PushPuzzle | null = null;
  for (let attempt = 0; attempt < 30; attempt++) {
    const wall = new Array<boolean>(cols * rows).fill(false);
    for (let r = 0; r < rows; r++)
      for (let c = 0; c < cols; c++) if (r === 0 || c === 0 || r === rows - 1 || c === cols - 1) wall[r * cols + c] = true;
    const interior = wall.map((w, i) => (w ? -1 : i)).filter((i) => i >= 0);
    for (const c of rng.sample(interior, nRocks)) wall[c] = true;
    const floor = interior.filter((i) => !wall[i]);
    // floor must stay connected
    const conn = bfsDistances(cols, rows, floor[0], (_a, b) => !wall[b]);
    if (floor.some((f) => conn[f] < 0)) continue;
    const grid: PushGrid = { cols, rows, wall, pads: [] };
    // pads away from dead corners so crates can be pulled off them
    const padCands = floor.filter((f) => !isCornerDead({ ...grid, pads: [] }, f));
    if (padCands.length < nCrates + 1) continue;
    const pads = rng.sample(padCands, nCrates);
    grid.pads = pads;
    let crates = pads.slice();
    const freeForPlayer = floor.filter((f) => !crates.includes(f));
    let player = rng.pick(freeForPlayer);
    let pulls = 0;
    for (let step = 0; step < scramble * 12 && pulls < scramble; step++) {
      const d = rng.pick(DIRS);
      const nx = stepCell(player, d, cols, rows);
      if (nx < 0 || wall[nx] || crates.includes(nx)) continue;
      const behind = stepCell(player, OPPOSITE[d], cols, rows);
      const ci = crates.indexOf(behind);
      if (ci >= 0 && rng.chance(0.7)) {
        crates = crates.slice();
        crates[ci] = player;
        pulls++;
      }
      player = nx;
    }
    const start: PushState = { player, crates };
    const off = crates.filter((c) => !pads.includes(c)).length;
    if (off === 0) continue;
    const sol = solvePush(grid, start, 30000);
    if (!sol || sol.length === 0) continue;
    const puz: PushPuzzle = { ...grid, start, minPushes: sol.length };
    const score = sol.length + (off === nCrates ? 100 : 0);
    const bestScore = best ? best.minPushes + (best.start.crates.every((c) => !best!.pads.includes(c)) ? 100 : 0) : -1;
    if (score > bestScore) best = puz;
    if (off === nCrates && sol.length >= minPushes && attempt >= 2) break;
  }
  if (!best) {
    // trivial safe fallback: one crate, one push
    const wall = new Array<boolean>(cols * rows).fill(false);
    for (let r = 0; r < rows; r++)
      for (let c = 0; c < cols; c++) if (r === 0 || c === 0 || r === rows - 1 || c === cols - 1) wall[r * cols + c] = true;
    const mid = Math.floor(rows / 2) * cols;
    return { cols, rows, wall, pads: [mid + 3], start: { player: mid + 1, crates: [mid + 2] }, minPushes: 1 };
  }
  return best;
}

/** Generous move allowance used for validation (optimal walk+push solution x2 + slack). */
export function pushMoveLimit(p: PushPuzzle): number {
  return p.minPushes * 12 + 30;
}

/* ---------------------------------------------------------- hidden scene */

export interface HiddenParams {
  targets: number;
  distractors: number;
}

/** Scene units; the renderer scales them uniformly into its box. */
export const SCENE_W = 100;
export const SCENE_H = 128;

export interface HiddenLeaf {
  x: number;
  y: number;
  size: number;
  rot: number;
}

export interface HiddenItem {
  id: number;
  name: ItemName;
  /** center in scene units */
  x: number;
  y: number;
  size: number;
  rot: number;
  target: boolean;
  leaf: HiddenLeaf | null;
}

export interface HiddenDecor {
  kind: 'fern' | 'bush' | 'flower' | 'rock' | 'mushroom';
  x: number;
  y: number;
  size: number;
  flip: boolean;
}

export interface HiddenScene {
  items: HiddenItem[];
  /** item ids to find, in strip order */
  targetIds: number[];
  decor: HiddenDecor[];
}

/** Items that look at home in the jungle (all valid ItemIcon names). */
export const JUNGLE_ITEMS: ItemName[] = [
  'banana', 'apple', 'cherry', 'grapes', 'strawberry', 'orange', 'watermelon', 'pear',
  'lion', 'frog', 'owl', 'monkey', 'turtle', 'butterfly', 'elephant', 'parrot', 'rabbit', 'panda',
  'flower', 'mushroom', 'gem', 'key', 'crown', 'coinbag', 'compass', 'bell', 'drum', 'hat', 'star', 'shell', 'fish', 'ball',
];

/** Fraction of an item's disc covered by its leaf (approx, by sampling). */
export function leafCoverage(it: HiddenItem): number {
  if (!it.leaf) return 0;
  const r = it.size / 2;
  const lr = it.leaf.size / 2;
  let inside = 0;
  let total = 0;
  for (let i = 0; i < 24; i++)
    for (let j = 0; j < 24; j++) {
      const x = it.x - r + ((i + 0.5) / 24) * 2 * r;
      const y = it.y - r + ((j + 0.5) / 24) * 2 * r;
      if ((x - it.x) ** 2 + (y - it.y) ** 2 > r * r) continue;
      total++;
      if ((x - it.leaf.x) ** 2 + (y - it.leaf.y) ** 2 <= lr * lr * 0.55) inside++; // leaf is an ellipse ~ 0.55 area of its box disc
    }
  return total ? inside / total : 0;
}

export function generateHiddenScene(seed: number, p: HiddenParams): HiddenScene {
  const rng = createRng(seed);
  const nT = clamp(Math.round(p.targets || 3), 1, 10);
  const nD = clamp(Math.round(p.distractors || 6), 0, 24);
  const pool = rng.shuffle(JUNGLE_ITEMS);
  const targets = pool.slice(0, nT);
  const rest = pool.slice(nT);
  const names: { name: ItemName; target: boolean }[] = [
    ...targets.map((name) => ({ name, target: true })),
    ...Array.from({ length: nD }, (_, i) => ({ name: rest[i % rest.length], target: false })),
  ];
  const order = rng.shuffle(names);
  let size = clamp(24 - (nT + nD) * 0.42, 13, 21);
  let items: HiddenItem[] = [];
  for (let tries = 0; tries < 30; tries++) {
    items = [];
    let ok = true;
    for (let k = 0; k < order.length && ok; k++) {
      const s = size * (order[k].target ? 1 : rng.int(90, 110) / 100);
      let placed = false;
      for (let a = 0; a < 300; a++) {
        const x = rng.int(Math.ceil(s / 2 + 2), Math.floor(SCENE_W - s / 2 - 2));
        const y = rng.int(Math.ceil(s / 2 + 6), Math.floor(SCENE_H - s / 2 - 3));
        if (items.some((o) => Math.hypot(o.x - x, o.y - y) < (o.size + s) / 2 + 1.5)) continue;
        items.push({ id: k, name: order[k].name, x, y, size: s, rot: rng.int(-25, 25), target: order[k].target, leaf: null });
        placed = true;
        break;
      }
      ok = placed;
    }
    if (ok) break;
    size *= 0.93;
  }
  for (const it of items) {
    if (!it.target && !rng.chance(0.45)) continue;
    const ang = rng.next() * Math.PI * 2;
    const ls = it.size * (it.target ? 0.8 : 0.75);
    const dist = it.size * 0.5;
    it.leaf = { x: it.x + Math.cos(ang) * dist, y: it.y + Math.sin(ang) * dist, size: ls, rot: Math.round((ang * 180) / Math.PI) + 90 };
    // keep most of the target visible
    while (leafCoverage(it) > 0.35 && it.leaf.size > 4) it.leaf.size *= 0.85;
  }
  const decor: HiddenDecor[] = [];
  const kinds: HiddenDecor['kind'][] = ['fern', 'bush', 'flower', 'rock', 'mushroom', 'fern', 'bush'];
  for (let i = 0; i < 14; i++)
    decor.push({ kind: rng.pick(kinds), x: rng.int(0, SCENE_W), y: rng.int(30, SCENE_H), size: rng.int(14, 30), flip: rng.chance(0.5) });
  decor.sort((a, b) => a.y - b.y);
  const targetIds = items.filter((i) => i.target).map((i) => i.id);
  return { items, targetIds, decor };
}
